"""Materi lengkap Tahap 1 · Dasar statistika (pendalaman, contoh kedua, soal latihan, referensi)."""
from .lengkap import L

R_WAL = "Walpole, R.E., Myers, R.H., Myers, S.L. & Ye, K. (2012). Probability & Statistics for Engineers & Scientists, 9th ed. Pearson."
R_MR = "Montgomery, D.C. & Runger, G.C. (2014). Applied Statistics and Probability for Engineers, 6th ed. Wiley."
R_MOORE = "Moore, D.S., McCabe, G.P. & Craig, B.A. (2017). Introduction to the Practice of Statistics, 9th ed. W.H. Freeman."
R_STD = "Steel, R.G.D., Torrie, J.H. & Dickey, D.A. (1997). Principles and Procedures of Statistics: A Biometrical Approach, 3rd ed. McGraw-Hill."
R_MONT = "Montgomery, D.C. (2017). Design and Analysis of Experiments, 9th ed. Wiley."
R_GOMEZ = "Gomez, K.A. & Gomez, A.A. (1984). Statistical Procedures for Agricultural Research, 2nd ed. Wiley."
R_MATT = "Mattjik, A.A. & Sumertajaya, I.M. Perancangan Percobaan dengan Aplikasi SAS dan Minitab. Bogor: IPB Press."
R_KUT = "Kutner, M.H., Nachtsheim, C.J., Neter, J. & Li, W. (2005). Applied Linear Statistical Models, 5th ed. McGraw-Hill/Irwin."
R_COHEN = "Cohen, J. (1988). Statistical Power Analysis for the Behavioral Sciences, 2nd ed. Lawrence Erlbaum."
R_COCH = "Cochran, W.G. (1977). Sampling Techniques, 3rd ed. Wiley."
R_HSU = "Hsu, J.C. (1996). Multiple Comparisons: Theory and Methods. Chapman & Hall."
R_HOLM = "Holm, S. (1979). A simple sequentially rejective multiple test procedure. Scandinavian Journal of Statistics, 6(2), 65–70."
R_BOXCOX = "Box, G.E.P. & Cox, D.R. (1964). An analysis of transformations. Journal of the Royal Statistical Society B, 26(2), 211–252."
R_SW = "Shapiro, S.S. & Wilk, M.B. (1965). An analysis of variance test for normality (complete samples). Biometrika, 52(3–4), 591–611."
R_EFRON = "Efron, B. & Tibshirani, R.J. (1993). An Introduction to the Bootstrap. Chapman & Hall."
R_AC = "Agresti, A. & Coull, B.A. (1998). Approximate is better than “exact” for interval estimation of binomial proportions. The American Statistician, 52(2), 119–126."
R_HURL = "Hurlbert, S.H. (1984). Pseudoreplication and the design of ecological field experiments. Ecological Monographs, 54(2), 187–211."
R_ANS = "Anscombe, F.J. (1973). Graphs in statistical analysis. The American Statistician, 27(1), 17–21."
R_DW = "Durbin, J. & Watson, G.S. (1950). Testing for serial correlation in least squares regression I. Biometrika, 37(3–4), 409–428."

# ---------------------------------------------------------------- 1. jenis data
L("dasar-jenis-data",
  [(r"Populasi, sampel, parameter, dan statistik",
    [r"Populasi adalah seluruh objek yang ingin disimpulkan, misalnya semua petak sawah di satu kabupaten. Sampel adalah bagian populasi yang benar-benar diamati. Ukuran yang menggambarkan populasi disebut parameter dan biasanya ditulis dengan huruf Yunani (\(\mu\), \(\sigma\), \(\pi\)); ukuran yang dihitung dari sampel disebut statistik dan ditulis dengan huruf Latin (\(\bar{x}\), \(s\), \(\hat{p}\)).",
     r"Statistik inferensia bekerja dua arah: dari sampel kita menaksir parameter (penaksiran), lalu menilai seberapa yakin taksiran itu (selang kepercayaan dan uji hipotesis). Karena sampel berbeda menghasilkan statistik berbeda, setiap statistik punya sebaran sendiri yang disebut sebaran penarikan sampel (sampling distribution)."],
    [r"\underbrace{\mu,\ \sigma^2,\ \pi}_{\text{parameter populasi}}\quad\longleftarrow\quad\underbrace{\bar{x},\ s^2,\ \hat{p}}_{\text{statistik sampel}}"]),
   (r"Teknik penarikan sampel",
    [r"Penarikan sampel acak sederhana memberi setiap anggota populasi peluang terpilih yang sama. Bila populasi terdiri atas lapisan yang berbeda (misalnya lahan sempit dan lahan luas), sampel acak berlapis (stratified) lebih teliti: sampel diambil dari setiap lapisan, lalu taksiran digabung dengan bobot ukuran lapisan.",
     r"Sampel klaster mengambil kelompok utuh (misalnya desa), murah tetapi kurang teliti bila anggota klaster mirip satu sama lain. Sampel sistematik mengambil setiap anggota ke-\(k\) dari daftar terurut. Sampel tidak acak (sampel kemudahan, sampel sukarela) tidak memungkinkan perhitungan galat penarikan sampel yang sah."],
    [r"\bar{y}_{st}=\sum_{h=1}^{H} W_h\,\bar{y}_h,\qquad W_h=\frac{N_h}{N},\qquad n_h=n\,\frac{N_h}{N}\ \ (\text{alokasi proporsional})"]),
   (r"Data percobaan dan data pengamatan",
    [r"Pada percobaan (eksperimen), peneliti menentukan perlakuan dan mengacaknya ke satuan percobaan, sehingga perbedaan respon dapat ditafsirkan sebagai akibat perlakuan. Pada studi pengamatan (observasional), peneliti hanya mencatat apa yang terjadi; hubungan yang ditemukan dapat dikacaukan oleh variabel pengganggu (confounder) yang memengaruhi prediktor dan respon sekaligus.",
     r"Itulah sebabnya rancangan percobaan menekankan pengacakan, sedangkan regresi pada data pengamatan memerlukan kehati-hatian: koefisien regresi menunjukkan asosiasi setelah variabel lain dalam model dikendalikan, bukan otomatis hubungan sebab-akibat."],
    []),
   (r"Menyiapkan data sebelum dianalisis",
    [r"Simpan data dalam format panjang (tidy): satu baris satu pengamatan, satu kolom satu variabel, baris pertama berisi nama kolom. Kolom faktor sebaiknya berisi teks (V1, V2) agar tidak terbaca sebagai angka. Periksa data hilang, salah ketik, satuan yang tercampur, dan nilai yang mustahil (misalnya tinggi negatif) sebelum menjalankan uji apa pun.",
     r"Data hilang tidak boleh diisi nol. Bila jumlahnya sedikit dan terjadi secara acak, analisis dengan data yang tersedia umumnya cukup; bila banyak atau berpola, laporkan dan pertimbangkan metode khusus. Pencilan diperiksa dulu penyebabnya: salah catat diperbaiki, sedangkan nilai ekstrem yang sah tetap dilaporkan."],
    [])],
  [(r"Tentukan skala pengukuran: nomor punggung pemain, peringkat lomba (juara 1, 2, 3), suhu dalam °C, dan bobot badan.",
    r"Nomor punggung: nominal (hanya label). Peringkat lomba: ordinal (berurutan, jarak tidak sama). Suhu °C: interval (nol sembarang). Bobot badan: rasio (nol mutlak)."),
   (r"Populasi 600 petani terdiri atas 360 petani lahan sempit dan 240 petani lahan luas. Dengan sampel 50 petani secara proporsional, berapa sampel tiap lapisan? Bila rata-rata produksi lapisan masing-masing 4,2 dan 6,0 ton, berapa taksiran rata-rata populasi?",
    r"Alokasi: \(50\times 360/600=30\) dan \(50\times 240/600=20\) petani. Taksiran: \(0{,}6\times 4{,}2+0{,}4\times 6{,}0=2{,}52+2{,}40=4{,}92\) ton."),
   (r"Survei menemukan petani yang memakai pupuk organik memiliki hasil lebih tinggi. Bolehkah disimpulkan pupuk organik menaikkan hasil?",
    r"Belum. Data ini observasional; petani pengguna pupuk organik mungkin juga punya modal, lahan, atau pengalaman yang berbeda (pengganggu). Kesimpulan sebab-akibat memerlukan percobaan dengan pengacakan, atau setidaknya pengendalian variabel pengganggu dalam model.")],
  [R_WAL, R_MOORE, R_COCH],
  contoh2=dict(judul="Contoh hitung kedua: taksiran dari sampel berlapis",
               soal="Populasi 1.000 kebun terbagi atas tiga lapisan menurut ketinggian. Diambil sampel 50 kebun secara proporsional. Rata-rata hasil tiap lapisan (ton/ha) tercatat di tabel. Taksir rata-rata populasi.",
               data=[["Lapisan", "N_h", "W_h", "n_h", "Rata-rata"], ["Dataran rendah", "500", "0,5", "25", "12"], ["Dataran sedang", "300", "0,3", "15", "15"], ["Dataran tinggi", "200", "0,2", "10", "20"]],
               langkah=[("Bobot lapisan adalah proporsi ukurannya terhadap populasi.", r"W_1=\frac{500}{1000}=0{,}5,\quad W_2=0{,}3,\quad W_3=0{,}2"),
                        (r"Alokasi proporsional membagi 50 sampel menurut bobot itu.", r"n_h=50\,W_h:\quad 25,\ 15,\ 10"),
                        (r"Rata-rata berlapis adalah rata-rata tertimbang rata-rata lapisan.", r"\bar{y}_{st}=0{,}5(12)+0{,}3(15)+0{,}2(20)=6+4{,}5+4=14{,}5")],
               simpul="Taksiran rata-rata populasi 14,5 ton/ha. Rata-rata sederhana tanpa bobot (15,67) akan berlebihan karena memberi bobot terlalu besar pada lapisan dataran tinggi yang kecil."))

# ---------------------------------------------------------------- 2. deskriptif
L("dasar-statistik-deskriptif",
  [(r"Kuartil, persentil, dan diagram kotak-garis",
    [r"Persentil ke-\(p\) adalah nilai yang membatasi \(p\%\) data terbawah. Kuartil pertama \(Q_1\), median \(Q_2\), dan kuartil ketiga \(Q_3\) adalah persentil ke-25, 50, dan 75. Lima angka (minimum, \(Q_1\), median, \(Q_3\), maksimum) diringkas dalam diagram kotak-garis (boxplot).",
     r"Aturan Tukey menandai pengamatan sebagai pencilan bila berada lebih dari 1,5 kali IQR di bawah \(Q_1\) atau di atas \(Q_3\). Aturan ini hanya penanda untuk diperiksa, bukan alasan otomatis membuang data. Perhatikan bahwa perangkat lunak memakai beberapa cara interpolasi kuartil, sehingga nilainya bisa sedikit berbeda pada sampel kecil."],
    [r"\text{batas bawah}=Q_1-1{,}5\,IQR,\qquad \text{batas atas}=Q_3+1{,}5\,IQR"]),
   (r"Rumus hitung cepat untuk ragam",
    [r"Jumlah kuadrat simpangan dapat dihitung tanpa terlebih dahulu menghitung setiap simpangan, cukup dari jumlah nilai dan jumlah kuadrat nilai. Bentuk ini dipakai untuk hitung manual dan juga menjadi dasar faktor koreksi (FK) pada tabel sidik ragam.",
     r"Untuk perhitungan komputer dengan bilangan besar, rumus dua langkah (hitung rata-rata dulu) lebih stabil secara numerik, karena rumus cepat mengurangkan dua bilangan besar yang hampir sama."],
    [r"\sum_{i=1}^{n}(x_i-\bar{x})^2=\sum_{i=1}^{n}x_i^2-\frac{\left(\sum_{i=1}^{n}x_i\right)^2}{n},\qquad FK=\frac{\left(\sum x_i\right)^2}{n}"]),
   (r"Data berkelompok dalam tabel frekuensi",
    [r"Bila data hanya tersedia dalam tabel frekuensi, setiap kelas diwakili titik tengahnya \(m_k\) dengan frekuensi \(f_k\). Rata-rata dan ragam lalu dihitung sebagai rata-rata tertimbang. Hasilnya adalah pendekatan, karena nilai asli di dalam kelas dianggap terkumpul di titik tengah.",
     r"Median data berkelompok dicari dengan interpolasi linear di dalam kelas median, yaitu kelas tempat frekuensi kumulatif melewati \(n/2\)."],
    [r"\bar{x}\approx\frac{\sum f_k m_k}{n},\qquad s^2\approx\frac{\sum f_k m_k^2-\left(\sum f_k m_k\right)^2/n}{n-1},\qquad \text{Me}\approx L+\frac{n/2-F}{f_{Me}}\,c"]),
   (r"Menyajikan ringkasan per kelompok",
    [r"Pada laporan percobaan, rata-rata tiap perlakuan biasanya disajikan bersama ukuran penyebaran. Pakai simpangan baku (rata-rata ± SD) bila ingin menggambarkan keragaman individu, dan galat baku (rata-rata ± SE) bila ingin menggambarkan ketelitian rata-rata. Selalu sebutkan mana yang dipakai beserta ukuran sampelnya.",
     r"Jumlah angka desimal disesuaikan dengan ketelitian alat ukur; biasanya satu desimal lebih banyak daripada data asli. Untuk data yang sangat miring, median dan IQR lebih jujur daripada rata-rata dan simpangan baku."],
    [])],
  [(r"Data: 4, 7, 7, 8, 10, 25. Hitung rata-rata dan median. Ukuran mana yang lebih mewakili pusat data?",
    r"Rata-rata \(=61/6=10{,}17\); median \(=(7+8)/2=7{,}5\). Median lebih mewakili karena nilai 25 menarik rata-rata ke atas."),
   (r"Diketahui \(n=5\), \(\sum x=50\), dan \(\sum x^2=530\). Hitung ragam dan simpangan baku dengan rumus cepat.",
    r"\(\sum(x-\bar{x})^2=530-50^2/5=530-500=30\). Ragam \(s^2=30/4=7{,}5\) dan \(s=\sqrt{7{,}5}=2{,}74\)."),
   (r"Sebuah data punya \(Q_1=12\) dan \(Q_3=18\). Apakah nilai 30 tergolong pencilan menurut aturan Tukey?",
    r"\(IQR=6\), batas atas \(=18+1{,}5(6)=27\). Nilai 30 melewati batas atas sehingga ditandai sebagai pencilan dan perlu diperiksa penyebabnya.")],
  [R_WAL, R_MOORE, R_STD],
  contoh2=dict(judul="Contoh hitung kedua: data berkelompok",
               soal="Bobot 20 buah (gram) hanya tersedia dalam tabel frekuensi berikut. Hitung rata-rata, ragam, dan simpangan baku pendekatan.",
               data=[["Kelas", "Titik tengah m", "Frekuensi f", "f·m", "f·m²"], ["10–14", "12", "3", "36", "432"], ["15–19", "17", "7", "119", "2.023"], ["20–24", "22", "6", "132", "2.904"], ["25–29", "27", "4", "108", "2.916"], ["Jumlah", "", "20", "395", "8.275"]],
               langkah=[("Rata-rata tertimbang titik tengah.", r"\bar{x}\approx\frac{395}{20}=19{,}75"),
                        (r"Jumlah kuadrat simpangan dengan rumus cepat.", r"\sum f m^2-\frac{(\sum f m)^2}{n}=8275-\frac{395^2}{20}=8275-7801{,}25=473{,}75"),
                        (r"Ragam dan simpangan baku dengan pembagi n − 1 = 19.", r"s^2\approx\frac{473{,}75}{19}=24{,}93,\qquad s\approx 4{,}99")],
               simpul="Rata-rata bobot sekitar 19,75 g dengan simpangan baku sekitar 4,99 g. Karena nilai asli diganti titik tengah, angka ini pendekatan; bila data mentah tersedia, hitung langsung dari data mentah."))

# ---------------------------------------------------------------- 3. normal
L("dasar-distribusi-normal",
  [(r"Sebaran rata-rata sampel",
    [r"Kombinasi linear peubah normal yang saling bebas juga menyebar normal. Akibatnya, rata-rata \(n\) pengamatan dari populasi normal menyebar normal dengan rata-rata \(\mu\) dan ragam \(\sigma^2/n\). Inilah dasar galat baku: makin besar \(n\), makin sempit sebaran \(\bar{X}\) di sekitar \(\mu\).",
     r"Bila populasinya tidak normal, teorema limit pusat menjamin hasil yang sama secara pendekatan untuk \(n\) cukup besar. Seberapa besar “cukup” bergantung pada kemiringan populasi: untuk sebaran yang hampir simetris \(n\approx 15\) sudah memadai, sedangkan sebaran yang sangat miring memerlukan lebih banyak."],
    [r"X_i\sim N(\mu,\sigma^2)\ \text{saling bebas}\ \Longrightarrow\ \bar{X}\sim N\!\left(\mu,\frac{\sigma^2}{n}\right),\qquad Z=\frac{\bar{X}-\mu}{\sigma/\sqrt{n}}\sim N(0,1)"]),
   (r"Sebaran turunan: khi-kuadrat, t, dan F",
    [r"Tiga sebaran yang dipakai di hampir semua uji berasal dari sebaran normal. Jumlah kuadrat \(k\) peubah normal baku menyebar khi-kuadrat dengan \(k\) derajat bebas. Normal baku dibagi akar khi-kuadrat per derajat bebasnya menyebar t. Rasio dua khi-kuadrat yang masing-masing dibagi derajat bebasnya menyebar F.",
     r"Dari sini lahir uji-uji yang dikenal: statistik t untuk rata-rata (karena \(\sigma\) ditaksir dengan \(s\)), uji khi-kuadrat untuk ragam, dan uji F pada sidik ragam sebagai rasio dua kuadrat tengah."],
    [r"\chi^2_k=\sum_{i=1}^{k}Z_i^2,\qquad t_k=\frac{Z}{\sqrt{\chi^2_k/k}},\qquad F_{k_1,k_2}=\frac{\chi^2_{k_1}/k_1}{\chi^2_{k_2}/k_2}",
     r"\frac{(n-1)s^2}{\sigma^2}\sim\chi^2_{n-1},\qquad \frac{\bar{X}-\mu}{s/\sqrt{n}}\sim t_{n-1}"]),
   (r"Pendekatan normal untuk binomial dan Poisson",
    [r"Sebaran binomial dengan \(n\) besar dapat didekati normal bila \(np\) dan \(n(1-p)\) keduanya minimal sekitar 10. Karena binomial diskret, tambahkan koreksi kontinuitas 0,5: peluang \(X\le k\) didekati dengan luas normal sampai \(k+0{,}5\). Sebaran Poisson dengan \(\lambda\) besar juga dapat didekati normal dengan rata-rata dan ragam \(\lambda\).",
     r"Pendekatan ini dipakai pada uji proporsi dan menjelaskan mengapa data cacahan dengan rata-rata besar sering tampak hampir normal."],
    [r"X\sim\text{Bin}(n,p)\ \approx\ N\big(np,\ np(1-p)\big),\qquad P(X\le k)\approx\Phi\!\left(\frac{k+0{,}5-np}{\sqrt{np(1-p)}}\right)"]),
   (r"Transformasi menuju normal",
    [r"Bila data jelas tidak normal, transformasi sering memperbaiki bentuk sebaran sekaligus menstabilkan ragam. Logaritma cocok untuk data positif yang miring ke kanan atau ragam yang sebanding dengan kuadrat rata-rata; akar kuadrat untuk cacahan; arcsin akar untuk proporsi. Transformasi Box-Cox memilih pangkat \(\lambda\) yang paling mendekatkan data ke normal.",
     r"Setelah analisis pada skala transformasi, laporkan hasil dalam skala asli dengan transformasi balik; ingat bahwa rata-rata logaritma yang dikembalikan adalah rata-rata geometrik, bukan rata-rata hitung."],
    [r"y^{(\lambda)}=\begin{cases}\dfrac{y^\lambda-1}{\lambda}, & \lambda\neq 0\\[4pt] \ln y, & \lambda=0\end{cases}\qquad y'=\sqrt{y+0{,}5},\qquad y'=\arcsin\sqrt{p}"])],
  [(r"Tinggi tanaman menyebar \(N(70,\ 8^2)\) cm. Berapa peluang satu tanaman lebih tinggi dari 82 cm?",
    r"\(z=(82-70)/8=1{,}5\). \(P(Z>1{,}5)=0{,}0668\), sekitar 6,7%."),
   (r"Dari populasi yang sama diambil 16 tanaman. Berapa peluang rata-rata sampelnya melebihi 74 cm?",
    r"\(SE=8/\sqrt{16}=2\), \(z=(74-70)/2=2\). \(P(Z>2)=0{,}0228\), sekitar 2,3%. Peluangnya jauh lebih kecil daripada satu tanaman karena rata-rata kurang beragam."),
   (r"Berapa tinggi yang menjadi batas 10% tanaman tertinggi?",
    r"Persentil ke-90 normal baku adalah \(z_{0{,}90}=1{,}2816\). Batasnya \(70+1{,}2816\times 8=80{,}25\) cm.")],
  [R_WAL, R_MR, R_BOXCOX],
  contoh2=dict(judul="Contoh hitung kedua: pendekatan normal untuk binomial",
               soal="Daya kecambah benih 30%. Dari 100 benih yang disemai, berapa peluang paling banyak 25 benih berkecambah?",
               data=None,
               langkah=[("Periksa syarat pendekatan: np dan n(1 − p) cukup besar.", r"np=30,\qquad n(1-p)=70"),
                        (r"Rata-rata dan simpangan baku sebaran binomial.", r"\mu=np=30,\qquad \sigma=\sqrt{np(1-p)}=\sqrt{21}=4{,}583"),
                        (r"Pakai koreksi kontinuitas: X ≤ 25 didekati dengan luas normal sampai 25,5.", r"z=\frac{25{,}5-30}{4{,}583}=-0{,}982"),
                        (r"Luas di bawah z dari tabel normal baku.", r"P(X\le 25)\approx\Phi(-0{,}982)=0{,}1631")],
               simpul="Peluangnya sekitar 16,3%, sangat dekat dengan peluang binomial eksak (0,1631). Tanpa koreksi kontinuitas hasilnya 0,1376, jauh lebih meleset."))

# ---------------------------------------------------------------- 4. uji hipotesis
L("dasar-uji-hipotesis",
  [(r"Uji dua sampel: bebas dan berpasangan",
    [r"Untuk dua kelompok yang saling bebas, uji t Welch membandingkan rata-rata tanpa mengandaikan ragam sama; derajat bebasnya ditaksir dengan rumus Welch–Satterthwaite. Uji t gabungan (pooled) hanya sah bila ragam kedua kelompok sama.",
     r"Bila pengamatan berpasangan (sebelum–sesudah pada subjek yang sama, atau dua perlakuan pada petak kembar), analisis dilakukan pada selisih tiap pasangan. Memasangkan menghilangkan keragaman antar subjek, sehingga uji berpasangan biasanya jauh lebih kuat daripada memperlakukan data sebagai dua kelompok bebas."],
    [r"t=\frac{\bar{x}_1-\bar{x}_2}{\sqrt{\dfrac{s_1^2}{n_1}+\dfrac{s_2^2}{n_2}}}\quad(\text{Welch}),\qquad t=\frac{\bar{d}}{s_d/\sqrt{n}},\ \ db=n-1\quad(\text{berpasangan})"]),
   (r"Uji satu arah dan dua arah",
    [r"Hipotesis alternatif dua arah (\(\mu\neq\mu_0\)) dipakai bila perbedaan ke arah mana pun penting. Alternatif satu arah (\(\mu>\mu_0\)) hanya sah bila arah ditetapkan sebelum melihat data dan perbedaan ke arah sebaliknya tidak bermakna bagi keputusan. P-value satu arah adalah separuh P-value dua arah bila statistik ke arah yang dihipotesiskan.",
     r"Memilih arah setelah melihat data menggandakan galat tipe I secara diam-diam; karena itu laporan ilmiah umumnya memakai uji dua arah."],
    [r"P_{\text{dua arah}}=2\,P\big(T_{db}\ge|t|\big),\qquad P_{\text{satu arah}}=P\big(T_{db}\ge t\big)"]),
   (r"Uji proporsi",
    [r"Untuk data biner (berhasil atau gagal), proporsi sampel \(\hat{p}=x/n\) dibandingkan dengan nilai hipotesis \(p_0\). Bila \(np_0\) dan \(n(1-p_0)\) cukup besar, statistik z menyebar mendekati normal baku. Untuk sampel kecil gunakan uji binomial eksak."],
    [r"z=\frac{\hat{p}-p_0}{\sqrt{p_0(1-p_0)/n}}"]),
   (r"Kuasa uji dan ukuran sampel",
    [r"Kuasa adalah peluang menolak \(H_0\) bila efek sebenarnya sebesar \(\delta\). Kuasa naik bila \(\delta\) besar, \(\sigma\) kecil, \(n\) besar, atau \(\alpha\) longgar. Sebelum percobaan, tentukan efek terkecil yang bermakna praktis, perkiraan \(\sigma\) (dari pustaka atau percobaan pendahuluan), \(\alpha\), dan kuasa sasaran (lazimnya 0,8 atau 0,9), lalu hitung \(n\).",
     r"Rumus di bawah memakai pendekatan normal; untuk sampel kecil hasilnya sedikit kurang dan biasanya ditambah satu atau dua."],
    [r"n_{\text{satu sampel}}=\left(\frac{(z_{1-\alpha/2}+z_{1-\beta})\,\sigma}{\delta}\right)^2,\qquad n_{\text{per kelompok}}=\frac{2\,(z_{1-\alpha/2}+z_{1-\beta})^2\sigma^2}{\delta^2}"]),
   (r"Uji nonparametrik pendamping",
    [r"Bila data jelas tidak normal dan ukuran sampel kecil, uji berbasis peringkat menjadi alternatif: uji peringkat bertanda Wilcoxon untuk data berpasangan atau satu sampel, uji Mann–Whitney (jumlah peringkat Wilcoxon) untuk dua kelompok bebas, dan Kruskal–Wallis untuk lebih dari dua kelompok. Uji ini menguji pergeseran letak sebaran, bukan rata-rata secara khusus, dan sedikit kurang kuat bila data sebenarnya normal."],
    [])],
  [(r"Sampel 25 petak memberi \(\bar{x}=52\) dan \(s=5\). Uji \(H_0:\mu=50\) dua arah pada \(\alpha=0{,}05\).",
    r"\(t=(52-50)/(5/\sqrt{25})=2{,}00\), \(db=24\), P dua arah \(=0{,}057\). \(H_0\) tidak ditolak pada 5% (walaupun uji satu arah ke atas memberi \(P=0{,}028\), arah itu harus ditetapkan sebelum melihat data)."),
   (r"Berapa ukuran sampel satu kelompok agar beda 5 satuan terdeteksi dengan kuasa 90% pada \(\alpha=0{,}05\) dua arah, bila \(\sigma=10\)?",
    r"\(n=\big((1{,}96+1{,}2816)\times 10/5\big)^2=42{,}0\). Bulatkan ke atas: 43 pengamatan."),
   (r"Dari 100 responden, 60 setuju. Ujilah apakah proporsi yang setuju berbeda dari 0,5.",
    r"\(z=(0{,}6-0{,}5)/\sqrt{0{,}25/100}=2{,}00\), P dua arah \(=0{,}0455\). Pada \(\alpha=0{,}05\), \(H_0\) ditolak: proporsi yang setuju berbeda dari separuh.")],
  [R_WAL, R_MR, R_COHEN],
  contoh2=dict(judul="Contoh hitung kedua: uji t berpasangan",
               soal="Enam tanaman diukur kadar klorofilnya sebelum dan sesudah diberi pupuk daun. Selisih (sesudah − sebelum) tercatat di tabel. Apakah pupuk menaikkan kadar klorofil?",
               data=[["Tanaman", "1", "2", "3", "4", "5", "6"], ["Selisih d", "2,1", "1,4", "3,0", "0,8", "1,9", "2,4"]],
               langkah=[("Rata-rata dan simpangan baku selisih.", r"\bar{d}=1{,}933,\qquad s_d=0{,}769"),
                        (r"Galat baku rata-rata selisih.", r"SE=\frac{0{,}769}{\sqrt{6}}=0{,}314"),
                        (r"Statistik t dengan db = 5.", r"t=\frac{1{,}933}{0{,}314}=6{,}16"),
                        (r"Bandingkan dengan nilai kritis atau hitung P-value dua arah.", r"t_{0{,}025;5}=2{,}571,\qquad P=0{,}0016")],
               simpul="Kenaikan rata-rata 1,93 satuan sangat nyata (P = 0,0016). Karena setiap tanaman menjadi pembanding dirinya sendiri, keragaman antar tanaman tidak ikut masuk ke galat."))

# ---------------------------------------------------------------- 5. selang kepercayaan
L("dasar-selang-kepercayaan",
  [(r"Tafsir yang benar",
    [r"Selang kepercayaan 95% berarti: bila pengambilan sampel diulang berkali-kali dan setiap kali dibuat selang dengan cara yang sama, sekitar 95% selang itu akan memuat parameter sebenarnya. Untuk satu selang yang sudah dihitung, parameter itu tetap (bukan acak); yang acak adalah selangnya.",
     r"Karena itu kalimat “peluang \(\mu\) berada di antara 17,9 dan 22,1 adalah 95%” kurang tepat dalam kerangka frekuentis. Kalimat yang aman: “kita 95% yakin selang 17,9 sampai 22,1 memuat \(\mu\)”, dengan keyakinan merujuk pada prosedurnya."],
    []),
   (r"Selang kepercayaan untuk proporsi",
    [r"Selang Wald \(\hat{p}\pm z\sqrt{\hat{p}(1-\hat{p})/n}\) mudah, tetapi cakupannya sering di bawah nominal bila \(n\) kecil atau \(\hat{p}\) dekat 0 atau 1, dan bisa melewati batas 0–1. Selang Wilson (skor) jauh lebih baik dan dianjurkan sebagai pilihan bawaan; alternatif sederhana yang hampir sama baiknya adalah Agresti–Coull, yaitu menambahkan dua keberhasilan dan dua kegagalan sebelum memakai rumus Wald."],
    [r"\text{Wilson:}\quad \frac{\hat{p}+\dfrac{z^2}{2n}}{1+\dfrac{z^2}{n}}\ \pm\ \frac{z}{1+\dfrac{z^2}{n}}\sqrt{\frac{\hat{p}(1-\hat{p})}{n}+\frac{z^2}{4n^2}}"]),
   (r"Selang kepercayaan untuk ragam",
    [r"Karena \((n-1)s^2/\sigma^2\) menyebar khi-kuadrat, selang untuk \(\sigma^2\) diperoleh dengan membalik kuantil khi-kuadrat. Selang ini tidak simetris di sekitar \(s^2\) dan sangat peka terhadap ketidaknormalan, sehingga gunakan dengan hati-hati."],
    [r"\frac{(n-1)s^2}{\chi^2_{1-\alpha/2;\,n-1}}\ \le\ \sigma^2\ \le\ \frac{(n-1)s^2}{\chi^2_{\alpha/2;\,n-1}}"]),
   (r"Hubungan dengan uji hipotesis",
    [r"Selang kepercayaan \(100(1-\alpha)\%\) dua arah memuat tepat semua nilai \(\mu_0\) yang tidak ditolak oleh uji dua arah pada taraf \(\alpha\). Jadi bila selang untuk selisih dua rata-rata memuat nol, selisihnya tidak nyata pada taraf itu. Selang lebih informatif daripada P-value karena sekaligus menunjukkan besar dan ketelitian efek."],
    []),
   (r"Selang bootstrap",
    [r"Bila rumus selang tidak tersedia atau asumsinya meragukan (misalnya untuk median atau rasio), selang dapat dibuat dengan bootstrap: ambil ulang sampel berukuran \(n\) dengan pengembalian dari data, hitung statistiknya, ulangi ribuan kali, lalu ambil persentil ke-2,5 dan ke-97,5 dari hasilnya sebagai selang 95% (metode persentil)."],
    [r"\hat{\theta}^{*(b)}=\hat{\theta}\big(x^{*(b)}_1,\dots,x^{*(b)}_n\big),\quad b=1,\dots,B;\qquad \text{SK 95\%}\approx\big[\hat{\theta}^*_{(0{,}025)},\ \hat{\theta}^*_{(0{,}975)}\big]"])],
  [(r"Sampel \(n=16\) memberi \(\bar{x}=20\) dan \(s=4\). Buat selang kepercayaan 95% untuk \(\mu\).",
    r"\(SE=4/4=1\), \(t_{0{,}025;15}=2{,}131\). Selang: \(20\pm2{,}131\), yaitu 17,87 sampai 22,13."),
   (r"Selang kepercayaan 95% untuk selisih rata-rata dua pupuk adalah −0,4 sampai 3,1 ton/ha. Apa kesimpulannya?",
    r"Selang memuat nol, sehingga selisihnya tidak nyata pada \(\alpha=0{,}05\). Namun selang juga menunjukkan selisih sampai 3,1 ton/ha masih mungkin; data belum cukup teliti untuk menyimpulkan tidak ada perbedaan."),
   (r"Sampel \(n=10\) memberi \(s^2=9\). Buat selang kepercayaan 95% untuk \(\sigma^2\).",
    r"\(\chi^2_{0{,}975;9}=19{,}023\) dan \(\chi^2_{0{,}025;9}=2{,}700\). Selang: \(81/19{,}023=4{,}26\) sampai \(81/2{,}700=30{,}0\).")],
  [R_WAL, R_MOORE, R_AC, R_EFRON],
  contoh2=dict(judul="Contoh hitung kedua: selang Wald dan Wilson untuk proporsi",
               soal="Dari 60 bibit, 18 terserang penyakit. Buat selang kepercayaan 95% untuk proporsi bibit terserang dengan cara Wald dan Wilson.",
               data=None,
               langkah=[("Proporsi sampel dan galat bakunya.", r"\hat{p}=\frac{18}{60}=0{,}30,\qquad SE=\sqrt{\frac{0{,}3\times0{,}7}{60}}=0{,}0592"),
                        (r"Selang Wald.", r"0{,}30\pm1{,}96(0{,}0592)\ \Rightarrow\ 0{,}184\ \text{sampai}\ 0{,}416"),
                        (r"Titik tengah Wilson bergeser sedikit ke arah 0,5.", r"\frac{0{,}30+\frac{1{,}96^2}{120}}{1+\frac{1{,}96^2}{60}}=0{,}312"),
                        (r"Lebar setengah selang Wilson.", r"\frac{1{,}96}{1+\frac{1{,}96^2}{60}}\sqrt{\frac{0{,}21}{60}+\frac{1{,}96^2}{4(60)^2}}=0{,}113"),
                        (r"Selang Wilson.", r"0{,}312\pm0{,}113\ \Rightarrow\ 0{,}199\ \text{sampai}\ 0{,}425")],
               simpul="Pada n = 60 kedua selang mirip; Wilson sedikit bergeser ke arah 0,5 dan cakupannya lebih dapat diandalkan. Perbedaannya makin besar bila n kecil atau proporsi mendekati 0 atau 1."))

# ---------------------------------------------------------------- 6. asumsi residual
L("dasar-asumsi-residual",
  [(r"Memeriksa normalitas: grafik dan uji formal",
    [r"Normalitas yang diperiksa adalah normalitas residual, bukan normalitas data mentah per kolom. Grafik kuantil-kuantil (Q-Q plot) menempatkan residual terurut terhadap kuantil normal; titik yang mengikuti garis lurus menandakan normalitas, ujung yang melengkung menandakan ekor yang berat atau kemiringan.",
     r"Uji Shapiro–Wilk adalah uji normalitas yang paling kuat untuk sampel kecil sampai sedang. Uji Kolmogorov–Smirnov dengan koreksi Lilliefors juga sering dipakai. Pada sampel besar, uji formal mudah menolak penyimpangan kecil yang tidak berarti, sedangkan pada sampel kecil mudah gagal mendeteksi penyimpangan besar; karena itu baca uji bersama grafiknya."],
    [r"W=\frac{\left(\sum_{i=1}^{n}a_i\,e_{(i)}\right)^2}{\sum_{i=1}^{n}(e_i-\bar{e})^2},\qquad 0<W\le 1"]),
   (r"Uji homogenitas ragam: Bartlett dan Levene",
    [r"Uji Bartlett membandingkan ragam kelompok dengan statistik khi-kuadrat, tetapi sangat peka terhadap ketidaknormalan. Uji Levene lebih tahan: ia menjalankan ANOVA satu arah pada simpangan mutlak tiap pengamatan dari rata-rata kelompoknya. Versi Brown–Forsythe memakai median kelompok dan lebih tahan lagi terhadap data miring.",
     r"Pedoman praktis: bila rasio ragam terbesar terhadap terkecil di bawah sekitar 3 dan ukuran kelompok seimbang, ANOVA cukup tahan terhadap ketidakhomogenan."],
    [r"z_{ij}=\big|y_{ij}-\bar{y}_{i\cdot}\big|,\qquad W_{\text{Levene}}=\frac{(N-t)\sum_i n_i(\bar{z}_{i\cdot}-\bar{z}_{\cdot\cdot})^2}{(t-1)\sum_i\sum_j(z_{ij}-\bar{z}_{i\cdot})^2}"]),
   (r"Statistik Durbin–Watson",
    [r"Untuk data berurutan menurut waktu atau tempat, statistik Durbin–Watson menguji autokorelasi orde satu pada residual. Nilainya mendekati \(2(1-\hat{\rho})\): sekitar 2 berarti tidak ada autokorelasi, mendekati 0 berarti autokorelasi positif, mendekati 4 berarti autokorelasi negatif.",
     r"Keputusan dibuat dengan batas \(d_L\) dan \(d_U\) dari tabel menurut \(n\) dan banyak prediktor: \(d<d_L\) berarti autokorelasi positif nyata, \(d>d_U\) berarti tidak nyata, dan di antara keduanya tidak dapat disimpulkan."],
    [r"d=\frac{\sum_{t=2}^{n}(e_t-e_{t-1})^2}{\sum_{t=1}^{n}e_t^2}\ \approx\ 2(1-\hat{\rho})"]),
   (r"Memilih transformasi dengan Box-Cox",
    [r"Box-Cox mencari pangkat \(\lambda\) yang memaksimumkan likelihood model setelah respon ditransformasi. Dalam praktik \(\lambda\) dibulatkan ke nilai yang mudah ditafsirkan: 1 (tanpa transformasi), 0,5 (akar), 0 (logaritma), −1 (kebalikan). Bila selang kepercayaan untuk \(\lambda\) memuat 1, transformasi tidak diperlukan.",
     r"Hubungan rata-rata dan ragam juga dapat menuntun pilihan: bila simpangan baku kelompok sebanding dengan rata-rata, pakai logaritma; bila ragam sebanding dengan rata-rata (cacahan), pakai akar."],
    [r"\sigma_i\propto\mu_i^{\,1-\lambda}\quad\Longrightarrow\quad \lambda=1-\text{kemiringan}\ \big(\ln s_i\ \text{terhadap}\ \ln\bar{y}_i\big)"]),
   (r"Aditivitas: uji satu derajat bebas Tukey",
    [r"Pada rancangan berkelompok tanpa ulangan per sel, model mengandaikan pengaruh kelompok dan perlakuan bersifat aditif. Uji Tukey untuk ketidakaditifan memisahkan satu derajat bebas dari galat untuk mendeteksi interaksi berbentuk perkalian. Bila nyata, transformasi logaritma sering mengembalikan sifat aditif."],
    [r"JK_{\text{nonaditif}}=\frac{\left[\sum_i\sum_j y_{ij}(\bar{y}_{i\cdot}-\bar{y}_{\cdot\cdot})(\bar{y}_{\cdot j}-\bar{y}_{\cdot\cdot})\right]^2}{\sum_i(\bar{y}_{i\cdot}-\bar{y}_{\cdot\cdot})^2\sum_j(\bar{y}_{\cdot j}-\bar{y}_{\cdot\cdot})^2}"])],
  [(r"Regresi dengan \(n=30\) dan satu prediktor menghasilkan \(d=0{,}90\). Dari tabel, \(d_L=1{,}35\) dan \(d_U=1{,}49\). Apa kesimpulannya?",
    r"\(d=0{,}90<d_L=1{,}35\), sehingga ada autokorelasi positif yang nyata. Galat baku regresi biasa terlalu kecil; pertimbangkan model deret waktu atau galat baku yang tahan autokorelasi."),
   (r"Data cacahan serangga menunjukkan ragam yang naik seiring rata-rata kelompok. Tindakan apa yang sesuai?",
    r"Transformasi akar \(\sqrt{y+0{,}5}\) untuk menstabilkan ragam, atau lebih baik memodelkan langsung dengan regresi Poisson atau binomial negatif."),
   (r"Box-Cox memberi \(\hat{\lambda}=0{,}08\) dengan selang 95% −0,20 sampai 0,35. Transformasi apa yang dipilih?",
    r"Selang memuat 0 dan tidak memuat 1, sehingga pilih transformasi logaritma \(\ln y\).")],
  [R_KUT, R_MONT, R_SW, R_BOXCOX, R_DW],
  contoh2=dict(judul="Contoh hitung kedua: statistik Durbin–Watson",
               soal="Delapan residual berurutan waktu dari sebuah regresi tercatat di tabel. Hitung statistik Durbin–Watson dan taksiran autokorelasinya.",
               data=[["t", "1", "2", "3", "4", "5", "6", "7", "8"], ["e_t", "0,5", "0,8", "0,3", "−0,2", "−0,6", "−0,4", "0,1", "0,4"]],
               langkah=[("Jumlah kuadrat selisih residual berurutan.", r"\sum_{t=2}^{8}(e_t-e_{t-1})^2=0{,}09+0{,}25+0{,}25+0{,}16+0{,}04+0{,}25+0{,}09=1{,}13"),
                        (r"Jumlah kuadrat residual.", r"\sum_{t=1}^{8}e_t^2=1{,}71"),
                        (r"Statistik d dan taksiran autokorelasi.", r"d=\frac{1{,}13}{1{,}71}=0{,}661,\qquad \hat{\rho}\approx1-\frac{d}{2}=0{,}67")],
               simpul="Nilai d = 0,66 jauh di bawah 2: residual yang berdekatan cenderung bertanda sama (autokorelasi positif). Pada data deret waktu, asumsi galat saling bebas tidak terpenuhi."))

# ---------------------------------------------------------------- 7. prinsip rancangan
L("dasar-prinsip-rancangan",
  [(r"Satuan percobaan dan pseudoreplikasi",
    [r"Satuan percobaan adalah satuan terkecil yang menerima perlakuan secara bebas melalui pengacakan, misalnya satu pot, satu petak, atau satu kandang. Satuan pengamatan adalah tempat pengukuran dilakukan, misalnya tiap tanaman dalam pot. Ulangan dihitung dari banyaknya satuan percobaan, bukan banyaknya pengukuran.",
     r"Memperlakukan pengukuran ganda dalam satu satuan percobaan sebagai ulangan disebut pseudoreplikasi. Akibatnya derajat bebas galat terlalu besar, galat baku terlalu kecil, dan P-value terlalu optimistis. Solusinya: rata-ratakan pengamatan per satuan percobaan, atau modelkan sebagai rancangan tersarang."],
    []),
   (r"Struktur perlakuan dan struktur rancangan",
    [r"Setiap percobaan punya dua struktur yang terpisah. Struktur perlakuan menjelaskan perlakuan apa yang dibandingkan: satu faktor, faktorial, atau faktorial dengan kontrol. Struktur rancangan menjelaskan bagaimana perlakuan diacak ke satuan percobaan: RAL, RAK, bujur sangkar Latin, atau petak terbagi.",
     r"Keduanya digabung dalam satu model; misalnya “faktorial 3×2 dalam RAK” berarti struktur perlakuan faktorial dan struktur rancangan acak kelompok. Memisahkan keduanya memudahkan memilih analisis yang tepat."],
    []),
   (r"Kontrol, plasebo, dan pembutaan",
    [r"Perlakuan kontrol menjadi patokan pembanding: kontrol negatif (tanpa perlakuan), kontrol positif (perlakuan standar yang sudah diketahui bekerja), atau plasebo pada percobaan yang melibatkan manusia. Pembutaan (blinding) mencegah pengamat atau subjek mengetahui perlakuan sehingga penilaian tidak bias, terutama untuk respon subjektif seperti skor kerusakan atau uji rasa."],
    []),
   (r"Ukuran ulangan berdasarkan kuasa",
    [r"Banyak ulangan sebaiknya ditentukan dari kuasa, bukan kebiasaan. Untuk membandingkan dua perlakuan dengan beda terkecil yang ingin dideteksi \(\delta\) dan simpangan baku galat \(\sigma\), rumus pendekatan normal memberi ulangan per perlakuan. Untuk \(t\) perlakuan pada ANOVA, kuasa dihitung dari sebaran F nonsentral dengan parameter nonsentralitas \(\lambda\).",
     r"Pedoman lama yang sering dipakai pada percobaan lapangan adalah derajat bebas galat minimal sekitar 12–15, karena di bawah itu nilai kritis F dan t naik tajam sehingga uji kehilangan kuasa."],
    [r"r\approx\frac{2\,(z_{1-\alpha/2}+z_{1-\beta})^2\sigma^2}{\delta^2},\qquad \lambda=\frac{r\sum_{i=1}^{t}\tau_i^2}{\sigma^2}"]),
   (r"Melakukan pengacakan",
    [r"Pada RAL, seluruh \(t\times r\) satuan percobaan diberi nomor, lalu perlakuan dialokasikan menurut urutan bilangan acak. Pada RAK, pengacakan dilakukan terpisah di dalam setiap kelompok sehingga setiap perlakuan muncul sekali per kelompok. Catat hasil pengacakan (denah) sebelum percobaan dimulai, dan jangan mengubah denah setelah melihat kondisi lapangan."],
    [])],
  [(r"Empat pot per perlakuan, dan di setiap pot ada lima tanaman yang diukur tingginya. Berapa ulangan per perlakuan?",
    r"Empat, karena pot adalah satuan percobaan yang menerima perlakuan. Lima tanaman per pot adalah subsampel; perlakukan 20 tanaman sebagai ulangan adalah pseudoreplikasi."),
   (r"Berapa ulangan per perlakuan agar beda 2 satuan antara dua perlakuan terdeteksi dengan kuasa 80% pada \(\alpha=0{,}05\), bila \(\sigma=3\)?",
    r"\(r\approx2(1{,}96+0{,}8416)^2(9)/4=35{,}3\). Bulatkan ke atas: 36 ulangan per perlakuan."),
   (r"Lahan percobaan memiliki kemiringan dari utara ke selatan. Bagaimana kelompok disusun pada RAK?",
    r"Kelompok dibuat memanjang tegak lurus arah kemiringan (barat–timur), sehingga setiap kelompok berada pada ketinggian yang hampir sama dan keragaman akibat kemiringan masuk ke komponen kelompok, bukan ke galat.")],
  [R_MONT, R_GOMEZ, R_MATT, R_HURL],
  contoh2=dict(judul="Contoh hitung kedua: menentukan banyak ulangan",
               soal="Peneliti ingin membandingkan dua varietas. Dari percobaan sebelumnya, simpangan baku galat sekitar 4 kuintal/ha. Beda terkecil yang bermakna secara agronomi adalah 3 kuintal/ha. Berapa ulangan yang diperlukan untuk kuasa 80% pada α = 0,05 dua arah?",
               data=None,
               langkah=[("Kuantil normal untuk α/2 = 0,025 dan kuasa 0,80.", r"z_{0{,}975}=1{,}960,\qquad z_{0{,}80}=0{,}842"),
                        (r"Masukkan ke rumus ulangan per perlakuan.", r"r\approx\frac{2(1{,}960+0{,}842)^2(4)^2}{3^2}=\frac{2(7{,}849)(16)}{9}=27{,}9"),
                        (r"Bulatkan ke atas.", r"r=28\ \text{ulangan per varietas}")],
               simpul="Diperlukan sekitar 28 ulangan per varietas. Bila tidak mungkin, pilihannya: menerima kuasa lebih rendah, menurunkan σ dengan pengelompokan atau satuan percobaan yang lebih seragam, atau menargetkan beda yang lebih besar."))

# ---------------------------------------------------------------- 8. ANOVA
L("dasar-anova",
  [(r"Asumsi dan diagnostik",
    [r"Uji F pada ANOVA sah bila galat saling bebas, menyebar normal, dan memiliki ragam yang sama di semua perlakuan. Kebebasan dijamin terutama oleh pengacakan. Normalitas diperiksa pada residual \(e_{ij}=y_{ij}-\bar{y}_{i\cdot}\) dengan Q-Q plot atau Shapiro–Wilk. Kehomogenan ragam diperiksa dengan uji Levene dan plot residual terhadap nilai dugaan.",
     r"ANOVA cukup tahan terhadap ketidaknormalan ringan, apalagi bila ulangan seimbang. Pelanggaran yang paling merusak adalah ketidakbebasan (misalnya pseudoreplikasi) dan ragam yang sangat berbeda bersama ukuran kelompok yang tidak sama."],
    [r"e_{ij}=y_{ij}-\hat{y}_{ij}=y_{ij}-\bar{y}_{i\cdot}"]),
   (r"Ukuran efek: eta-kuadrat dan omega-kuadrat",
    [r"P-value tidak menunjukkan seberapa besar pengaruh perlakuan. Eta-kuadrat \(\eta^2\) adalah proporsi keragaman total yang diterangkan perlakuan, tetapi cenderung berlebihan pada sampel kecil. Omega-kuadrat \(\omega^2\) mengoreksi bias itu dan lebih tepat untuk menggambarkan efek di populasi.",
     r"Cohen memberi patokan kasar untuk ANOVA: sekitar 0,01 kecil, 0,06 sedang, dan 0,14 besar. Patokan bidang ilmu masing-masing lebih bermakna bila tersedia."],
    [r"\eta^2=\frac{JKP}{JKT},\qquad \omega^2=\frac{JKP-(t-1)\,KTG}{JKT+KTG}"]),
   (r"Kontras ortogonal",
    [r"Kontras adalah kombinasi linear rata-rata perlakuan yang koefisiennya berjumlah nol, misalnya membandingkan kontrol dengan rata-rata dua perlakuan lain. Kontras yang direncanakan sebelum percobaan diuji langsung dengan F berderajat bebas satu, tanpa harus menunggu F keseluruhan nyata.",
     r"Dua kontras ortogonal bila jumlah hasil kali koefisiennya nol. Sebanyak \(t-1\) kontras yang saling ortogonal memecah JK perlakuan menjadi bagian-bagian yang jumlahnya tepat sama dengan JKP. Untuk perlakuan kuantitatif yang berjarak sama (misalnya dosis 0, 50, 100), kontras polinomial ortogonal menguji tren linear, kuadratik, dan seterusnya."],
    [r"L=\sum_{i=1}^{t}c_i\bar{y}_{i\cdot},\quad \sum c_i=0,\qquad JK_L=\frac{L^2}{\sum c_i^2/r},\qquad F=\frac{JK_L}{KTG}\sim F_{1,\,db_{\text{galat}}}",
     r"\text{ortogonal:}\ \sum_{i}c_{1i}c_{2i}=0;\qquad t=3\ \text{berjarak sama: linear}\ (-1,0,1),\ \text{kuadratik}\ (1,-2,1)"]),
   (r"Bila asumsi tidak dipenuhi",
    [r"Bila ragam tidak homogen, ANOVA Welch membandingkan rata-rata tanpa mengandaikan ragam sama, dengan bobot \(w_i=n_i/s_i^2\). Bila residual sangat tidak normal dan ulangan kecil, uji Kruskal–Wallis berbasis peringkat menjadi alternatif nonparametrik. Transformasi respon (logaritma, akar) sering menyelesaikan dua masalah sekaligus.",
     r"Apa pun pilihannya, tentukan berdasarkan diagnostik dan sifat data, bukan dengan mencoba beberapa uji lalu memilih yang memberi P terkecil."],
    [r"H=\frac{12}{N(N+1)}\sum_{i=1}^{t}\frac{R_i^2}{n_i}-3(N+1)\ \sim\ \chi^2_{t-1}"])],
  [(r"Percobaan 4 perlakuan dengan 5 ulangan memberi JKP = 60 dan JKT = 140. Lengkapi tabel ANOVA dan simpulkan pada \(\alpha=0{,}05\).",
    r"JKG \(=140-60=80\); db perlakuan 3, db galat 16. KTP \(=20\), KTG \(=5\), \(F=4{,}00\). \(F_{0{,}05;3,16}=3{,}24\), P \(=0{,}027\). Perlakuan berpengaruh nyata."),
   (r"Rata-rata tiga perlakuan adalah 10 (kontrol), 12, dan 15, dengan \(r=6\) dan KTG \(=4\). Uji kontras kontrol lawan rata-rata dua perlakuan lain.",
    r"Koefisien \((2,-1,-1)\): \(L=20-27=-7\). \(JK_L=49/(6/6)=49\), \(F=49/4=12{,}25\) dengan db 1 dan 15, P \(=0{,}003\). Kontrol nyata lebih rendah daripada rata-rata perlakuan lain."),
   (r"Mengapa \(\eta^2\) sering lebih besar daripada \(\omega^2\)?",
    r"\(\eta^2\) memakai JKP apa adanya, padahal JKP juga memuat keragaman galat acak sebesar sekitar \((t-1)KTG\). \(\omega^2\) mengurangkan bagian itu, sehingga lebih jujur menggambarkan efek di populasi, terutama pada sampel kecil.")],
  [R_MONT, R_STD, R_GOMEZ, R_MATT],
  contoh2=dict(judul="Contoh hitung kedua: memecah JK perlakuan dengan kontras ortogonal",
               soal="Lanjutan contoh tiga pakan (A, B, C) dengan empat ulangan: rata-rata 6, 8, dan 10 kg, JKP = 32, dan KTG = 0,667 (db galat 9). A adalah pakan standar. Pecah JKP menjadi dua kontras ortogonal: A lawan rata-rata (B, C), dan B lawan C.",
               data=[["Kontras", "c_A", "c_B", "c_C", "L", "JK"], ["A lawan (B, C)", "2", "−1", "−1", "−6", "24"], ["B lawan C", "0", "1", "−1", "−2", "8"]],
               langkah=[("Periksa ortogonalitas: jumlah hasil kali koefisien nol.", r"(2)(0)+(-1)(1)+(-1)(-1)=0"),
                        (r"Kontras pertama dan jumlah kuadratnya.", r"L_1=2(6)-8-10=-6,\qquad JK_1=\frac{(-6)^2}{6/4}=24"),
                        (r"Kontras kedua dan jumlah kuadratnya.", r"L_2=8-10=-2,\qquad JK_2=\frac{(-2)^2}{2/4}=8"),
                        (r"Jumlah keduanya sama dengan JK perlakuan.", r"JK_1+JK_2=24+8=32=JKP"),
                        (r"Uji F masing-masing kontras dengan db 1 dan 9.", r"F_1=\frac{24}{0{,}667}=36{,}0\ (P=0{,}0002),\qquad F_2=\frac{8}{0{,}667}=12{,}0\ (P=0{,}007)")],
               simpul="Kedua kontras nyata: pakan standar A lebih rendah daripada rata-rata pakan baru, dan C lebih baik daripada B. Ukuran efek keseluruhan besar: η² = 32/38 = 0,84 dan ω² = 0,79."))

# ---------------------------------------------------------------- 9. uji lanjut
L("dasar-uji-lanjut",
  [(r"Rumus nilai kritis",
    [r"Semua uji lanjut berpasangan membandingkan selisih dua rata-rata dengan suatu nilai kritis yang dibangun dari galat baku. Untuk ulangan sama \(r\), galat baku selisih adalah \(\sqrt{2KTG/r}\). Perbedaannya ada pada sebaran yang dipakai: BNT memakai t, BNJ (Tukey) memakai sebaran rentang ter-student \(q\), Duncan memakai \(q\) dengan taraf yang berubah menurut jarak peringkat, dan Scheffé memakai F sehingga sah untuk semua kontras.",
     r"Bila ulangan tidak sama, ganti \(2/r\) dengan \(1/r_i+1/r_j\) (Tukey–Kramer untuk BNJ)."],
    [r"BNT=t_{\alpha/2;\,db_g}\sqrt{\frac{2KTG}{r}},\qquad BNJ=q_{\alpha;\,t,\,db_g}\sqrt{\frac{KTG}{r}},\qquad S=\sqrt{(t-1)F_{\alpha;\,t-1,\,db_g}}\sqrt{\frac{2KTG}{r}}"]),
   (r"Laju galat per perbandingan dan per percobaan",
    [r"Bila setiap perbandingan diuji pada \(\alpha\), peluang sekurang-kurangnya satu kesimpulan palsu dalam satu percobaan (family-wise error rate, FWER) membengkak seiring banyaknya perbandingan. Untuk \(t\) perlakuan ada \(t(t-1)/2\) pasangan; enam perlakuan sudah menghasilkan 15 pasangan.",
     r"Koreksi Bonferroni menguji setiap perbandingan pada \(\alpha/m\); sederhana tetapi konservatif. Prosedur Holm lebih kuat dan tetap mengendalikan FWER: urutkan P-value dari terkecil, bandingkan P ke-\(k\) dengan \(\alpha/(m-k+1)\), dan berhenti pada kegagalan pertama."],
    [r"FWER\le 1-(1-\alpha)^m,\qquad \text{Bonferroni: }p_k\le\frac{\alpha}{m},\qquad \text{Holm: }p_{(k)}\le\frac{\alpha}{m-k+1}"]),
   (r"Uji lanjut bila ragam tidak homogen",
    [r"BNT, BNJ, dan Duncan memakai satu KTG gabungan sehingga mengandaikan ragam semua perlakuan sama. Bila ragam jelas berbeda, gunakan Games–Howell, yaitu versi Tukey yang memakai galat baku dan derajat bebas Welch untuk setiap pasangan."],
    [r"SE_{ij}=\sqrt{\frac{s_i^2}{n_i}+\frac{s_j^2}{n_j}},\qquad \text{beda nyata bila}\ \frac{|\bar{y}_i-\bar{y}_j|}{SE_{ij}}>\frac{q_{\alpha;\,t,\,db_{ij}}}{\sqrt{2}}"]),
   (r"Memilih uji lanjut",
    [r"Pilih uji sebelum melihat data, sesuai pertanyaan penelitian. Untuk beberapa perbandingan yang sudah direncanakan, BNT atau kontras sudah memadai. Untuk membandingkan semua pasangan, Tukey (BNJ) mengendalikan FWER dan menjadi pilihan bawaan yang aman. Untuk membandingkan setiap perlakuan dengan satu kontrol, Dunnett lebih kuat daripada Tukey. Untuk perlakuan kuantitatif (dosis, suhu), jangan memakai uji lanjut berpasangan; gunakan kontras polinomial atau regresi.",
     r"Duncan (DMRT) banyak dipakai pada pustaka pertanian karena lebih mudah menemukan beda, tetapi FWER-nya lebih longgar daripada Tukey; sebutkan dengan jelas uji mana yang dipakai."],
    [])],
  [(r"KTG = 4 dengan db galat 16, dan setiap perlakuan punya 5 ulangan. Hitung BNT 5%.",
    r"\(t_{0{,}025;16}=2{,}120\). \(BNT=2{,}120\sqrt{2(4)/5}=2{,}120(1{,}265)=2{,}68\). Dua rata-rata berbeda nyata bila selisihnya lebih dari 2,68."),
   (r"Dengan data yang sama dan 4 perlakuan, hitung BNJ (Tukey) 5% bila \(q_{0{,}05;4,16}=4{,}05\).",
    r"\(BNJ=4{,}05\sqrt{4/5}=4{,}05(0{,}894)=3{,}62\). BNJ lebih besar daripada BNT karena mengendalikan galat untuk seluruh 6 pasangan sekaligus."),
   (r"Bila enam perbandingan saling bebas masing-masing diuji pada \(\alpha=0{,}05\), berapa peluang sekurang-kurangnya satu positif palsu?",
    r"\(1-0{,}95^6=0{,}265\), sekitar 26,5%, jauh di atas 5%.")],
  [R_MONT, R_GOMEZ, R_STD, R_HSU, R_HOLM],
  contoh2=dict(judul="Contoh hitung kedua: koreksi Holm untuk empat perbandingan",
               soal="Empat perbandingan yang direncanakan memberi P-value 0,004; 0,019; 0,030; dan 0,21. Terapkan koreksi Bonferroni dan Holm pada FWER 5%.",
               data=[["Urutan k", "P", "Bonferroni (P × 4)", "Pembagi Holm", "P Holm (disesuaikan)"], ["1", "0,004", "0,016", "4", "0,016"], ["2", "0,019", "0,076", "3", "0,057"], ["3", "0,030", "0,120", "2", "0,060"], ["4", "0,210", "0,840", "1", "0,210"]],
               langkah=[("Bonferroni: kalikan setiap P dengan m = 4 (maksimum 1).", r"0{,}004\times4=0{,}016,\ \ 0{,}019\times4=0{,}076,\ \dots"),
                        (r"Holm: kalikan P terurut ke-k dengan m − k + 1.", r"0{,}004\times4=0{,}016,\quad 0{,}019\times3=0{,}057,\quad 0{,}030\times2=0{,}060,\quad 0{,}21\times1=0{,}21"),
                        (r"Jaga agar P yang disesuaikan tidak turun (ambil maksimum kumulatif), lalu bandingkan dengan 0,05.", r"0{,}016<0{,}05;\quad 0{,}057>0{,}05\ \Rightarrow\ \text{berhenti}")],
               simpul="Pada FWER 5%, hanya perbandingan dengan P = 0,004 yang tetap nyata. Tanpa koreksi, tiga perbandingan tampak nyata; dua di antaranya bisa saja positif palsu."))

# ---------------------------------------------------------------- 10. korelasi
L("dasar-korelasi",
  [(r"Koefisien determinasi dan besar korelasi",
    [r"Kuadrat korelasi \(r^2\) adalah proporsi keragaman satu variabel yang dapat diterangkan oleh hubungan linear dengan variabel lain. Korelasi 0,5 baru menerangkan 25% keragaman. Cohen memberi patokan kasar untuk \(|r|\): 0,1 kecil, 0,3 sedang, dan 0,5 besar; patokan bidang ilmu masing-masing lebih bermakna.",
     r"Nyata atau tidaknya korelasi sangat bergantung pada \(n\): dengan \(n=400\), korelasi 0,1 sudah nyata walaupun hubungannya hampir tidak berarti. Karena itu laporkan selang kepercayaannya, bukan hanya P-value."],
    [r"r^2=\frac{JK_{\text{regresi}}}{JK_{\text{total}}}"]),
   (r"Selang kepercayaan dengan transformasi Fisher",
    [r"Sebaran \(r\) tidak simetris bila \(\rho\) jauh dari nol, sehingga selang dibuat pada skala transformasi Fisher \(z=\tanh^{-1}(r)\) yang mendekati normal dengan galat baku \(1/\sqrt{n-3}\). Batas selang dikembalikan ke skala korelasi dengan \(\tanh\). Transformasi yang sama dipakai untuk membandingkan dua korelasi dari sampel yang saling bebas."],
    [r"z=\tfrac12\ln\frac{1+r}{1-r},\qquad z\pm\frac{z_{1-\alpha/2}}{\sqrt{n-3}},\qquad \rho\in\big[\tanh(z_L),\ \tanh(z_U)\big]"]),
   (r"Korelasi parsial",
    [r"Dua variabel dapat berkorelasi hanya karena keduanya dipengaruhi variabel ketiga. Korelasi parsial mengukur hubungan \(X\) dan \(Y\) setelah pengaruh linear \(Z\) dikeluarkan dari keduanya. Bila korelasi parsial jauh lebih kecil daripada korelasi biasa, sebagian besar hubungan semula disebabkan oleh \(Z\)."],
    [r"r_{XY\cdot Z}=\frac{r_{XY}-r_{XZ}\,r_{YZ}}{\sqrt{(1-r_{XZ}^2)(1-r_{YZ}^2)}}"]),
   (r"Kendall tau",
    [r"Selain Spearman, korelasi peringkat Kendall \(\tau\) mengukur keselarasan urutan dari jumlah pasangan yang searah (concordant) dikurangi pasangan yang berlawanan arah (discordant). Nilainya umumnya lebih kecil daripada Spearman untuk data yang sama, lebih tahan terhadap pencilan, dan punya tafsir peluang yang jelas."],
    [r"\tau=\frac{C-D}{n(n-1)/2}"]),
   (r"Batas-batas korelasi",
    [r"Korelasi Pearson hanya mengukur hubungan linear. Hubungan berbentuk U dapat memberi \(r\approx0\) walaupun kedua variabel jelas berkaitan. Empat himpunan data Anscombe memiliki rata-rata, ragam, dan korelasi yang hampir sama, tetapi pola grafiknya sangat berbeda; karena itu selalu buat diagram pencar.",
     r"Satu pencilan dapat menaikkan atau menurunkan \(r\) secara drastis, dan rentang data yang terbatas (restriction of range) menurunkan korelasi. Yang paling penting: korelasi tidak membuktikan sebab-akibat."],
    [])],
  [(r"Dari 20 pasang data diperoleh \(r=0{,}45\). Apakah korelasinya nyata pada \(\alpha=0{,}05\)?",
    r"\(t=0{,}45\sqrt{18}/\sqrt{1-0{,}2025}=2{,}14\) dengan db 18, P \(=0{,}046\). Korelasi nyata, tetapi hanya menerangkan \(r^2=20\%\) keragaman."),
   (r"Korelasi antara curah hujan dan hasil panen adalah 0,6. Berapa persen keragaman hasil yang dapat diterangkan oleh curah hujan secara linear?",
    r"\(r^2=0{,}36\), yaitu 36%."),
   (r"Diagram pencar menunjukkan pola U yang jelas, tetapi \(r=0{,}02\). Apa kesimpulannya?",
    r"Tidak ada hubungan linear, tetapi ada hubungan nonlinear yang kuat. Gunakan model yang sesuai bentuknya, misalnya regresi polinomial kuadratik.")],
  [R_WAL, R_MOORE, R_COHEN, R_ANS],
  contoh2=dict(judul="Contoh hitung kedua: selang kepercayaan korelasi",
               soal="Dari 30 petak diperoleh korelasi antara kadar nitrogen daun dan hasil sebesar r = 0,62. Buat selang kepercayaan 95% untuk ρ dan uji apakah korelasinya nyata.",
               data=None,
               langkah=[("Uji t untuk korelasi dengan db = 28.", r"t=\frac{0{,}62\sqrt{28}}{\sqrt{1-0{,}62^2}}=4{,}18,\qquad P=0{,}0003"),
                        (r"Transformasi Fisher dan galat bakunya.", r"z=\tanh^{-1}(0{,}62)=0{,}725,\qquad SE=\frac{1}{\sqrt{27}}=0{,}192"),
                        (r"Selang 95% pada skala z.", r"0{,}725\pm1{,}96(0{,}192)\ \Rightarrow\ 0{,}348\ \text{sampai}\ 1{,}102"),
                        (r"Kembalikan ke skala korelasi.", r"\tanh(0{,}348)=0{,}33,\qquad \tanh(1{,}102)=0{,}80")],
               simpul="Korelasi sangat nyata, dan ρ di populasi diperkirakan antara 0,33 dan 0,80. Selangnya tidak simetris di sekitar 0,62 dan cukup lebar, sehingga besar hubungan sebenarnya masih belum terlalu pasti dengan 30 petak."))
